// Parse the command line arguments, separating recognized Deno flags from the
// remaining arguments (which are passed through to the script).
pub fn set_flags(args: Vec<String>) -> (DenoFlags, Vec<String>) {
  // Let V8 consume the flags it understands first.
  let args = v8_set_flags(args);

  let mut flags = DenoFlags::default();
  let mut rest = Vec::new();
  for arg in args {
    match arg.as_str() {
      "-h" | "--help" => flags.help = true,
      "-D" | "--log-debug" => flags.log_debug = true,
      "-v" | "--version" => flags.version = true,
      "-r" | "--reload" => flags.reload = true,
      "--allow-write" => flags.allow_write = true,
      "--allow-net" => flags.allow_net = true,
      _ => rest.push(arg),
    }
  }
  (flags, rest)
}

